/* Sporting Pearls — minimal SplitType shim (Phase 5, CSP vendor step).
 *
 * The original dependency (unpkg.com/splittype@0.3.4) has disappeared
 * from npm/CDNs — the live site's <script src> 404s and the hero
 * word-reveal silently never ran. This shim implements the only API the
 * site uses:  new SplitType(target, { types: 'words' })  returning
 * { words: [<span class="word">…] }  — recursively splitting text nodes
 * so nested markup survives. Words are inline-block so GSAP transforms
 * apply. No other SplitType features are emulated.
 */
(function (window) {
  'use strict';
  function splitInto(node, words) {
    var children = Array.prototype.slice.call(node.childNodes);
    children.forEach(function (ch) {
      if (ch.nodeType === 3) {
        if (!ch.nodeValue.trim()) return;
        var frag = document.createDocumentFragment();
        ch.nodeValue.split(/(\s+)/).forEach(function (part) {
          if (!part) return;
          if (/^\s+$/.test(part)) { frag.appendChild(document.createTextNode(' ')); return; }
          var s = document.createElement('span');
          s.className = 'word';
          s.style.display = 'inline-block';
          s.textContent = part;
          frag.appendChild(s);
          words.push(s);
        });
        node.replaceChild(frag, ch);
      } else if (ch.nodeType === 1 && ch.tagName !== 'BR') {
        splitInto(ch, words);
      }
    });
  }
  function SplitType(target, opts) {
    opts = opts || {};
    var els;
    if (typeof target === 'string') els = document.querySelectorAll(target);
    else if (target && target.length !== undefined) els = target;
    else els = [target];
    var words = [];
    Array.prototype.slice.call(els || []).forEach(function (el) { splitInto(el, words); });
    return { words: words };
  }
  window.SplitType = SplitType;
})(window);
